ENTITY mega_memory IS -- Comentário: Declara a existência deste bloco, o batizando de 'mega_memory'
	PORT -- Comentário: Palavra-chave para iniciar a declaração dos furos onde conectaremos os fios (pinos)
	( -- Comentário: Abertura da lista de pinos
		address		: IN STD_LOGIC_VECTOR (4 DOWNTO 0); -- Comentário: Pino IN - Endereço. Vetor de 5 vias, suficiente para contar até 32 em binário
		clock		: IN STD_LOGIC  := '1'; -- Comentário: Pino IN - Fio do clock (o pulso síncrono da RAM), e se o usuário esquecer de ligar, ele assume estado alto '1'
		data		: IN STD_LOGIC_VECTOR (7 DOWNTO 0); -- Comentário: Pino IN - Fios de dados. Vetor de 8 vias (um byte inteiro) contendo a informação a ser salva
		wren		: IN STD_LOGIC ; -- Comentário: Pino IN - Write Enable. Fio que destrava o cofre da memória para gravar quando tem tensão (1)
		q		: OUT STD_LOGIC_VECTOR (7 DOWNTO 0) -- Comentário: Pino OUT - Onde a memória cospe de volta o byte de 8 vias que foi lido
	); -- Comentário: Fechamento da lista de pinos
END mega_memory; -- Comentário: Fim da definição do aspecto externo (a caixa) da entidade mega_memory
