		clock_enable_input_a => "BYPASS", -- Comentário: Parâmetro físico - Ignora a necessidade de liberar o clock na entrada (fica sempre habilitado)
		clock_enable_output_a => "BYPASS", -- Comentário: Parâmetro físico - Ignora a necessidade de liberar o clock na saída
		intended_device_family => "Cyclone III", -- Comentário: Parâmetro físico - A tecnologia dos transistores será construída para chip Cyclone III
		lpm_hint => "ENABLE_RUNTIME_MOD=YES,INSTANCE_NAME=Luan", -- Comentário: Parâmetro MÁGICO - Acorda o módulo JTAG (USB) no chip e batiza essa área com ID "Luan"
		lpm_type => "altsyncram", -- Comentário: Parâmetro físico - A categoria nativa deste bloquinho é altsyncram
		numwords_a => 32, -- Comentário: Parâmetro físico - Vamos instanciar 32 gavetas de endereço no silício
		operation_mode => "SINGLE_PORT", -- Comentário: Parâmetro físico - Operação travada em Porta Única (leitura e gravação dividem o mesmo pino de endereço)
		outdata_aclr_a => "NONE", -- Comentário: Parâmetro físico - O pino de "limpar/zerar saída de emergência" foi arrancado do chip (Não usado)
		outdata_reg_a => "UNREGISTERED", -- Comentário: Parâmetro físico - O dado sai rasgando pro mundo exterior sem esperar o próximo pulso de clock num Flip-Flop
		power_up_uninitialized => "FALSE", -- Comentário: Parâmetro físico - Ao colocar a placa na tomada, a memória será forçada a iniciar preenchida de zeros (falso para não iniciada)
		read_during_write_mode_port_a => "NEW_DATA_NO_NBE_READ", -- Comentário: Parâmetro físico - Se lermos e gravarmos ao mesmo tempo, a memória joga pro pino o dado Novo que estamos colocando
		widthad_a => 5, -- Comentário: Parâmetro físico - Largura da porta de endereço (gavetas) definida para 5 fios (2^5 = 32 posições)
		width_a => 8, -- Comentário: Parâmetro físico - Largura das gavetas definida para guardar 8 bits
		width_byteena_a => 1 -- Comentário: Parâmetro físico - Habilitação individual de Byte fixada em 1 (usamos palavras inteiras, sem fatiar)
	) -- Comentário: Fim das configurações físicas do M9K
	PORT MAP ( -- Comentário: Inicia o mapeamento elétrico (Soldando nossos pinos IN/OUT da entidade nas portas do bloco de silício configurado acima)
		address_a => address, -- Comentário: Solda o nosso pino 'address' na porta 'address_a' do chip
		clock0 => clock, -- Comentário: Solda o nosso pino 'clock' na porta 'clock0' do chip
		data_a => data, -- Comentário: Solda o nosso pino de entrada 'data' na porta 'data_a'
		wren_a => wren, -- Comentário: Solda nossa chave de liberação 'wren' na porta física 'wren_a'
		q_a => sub_wire0 -- Comentário: Solda a saída de dados real do chip ao nosso fio interno 'sub_wire0' (que lembramos, sobe até a saída 'q')
	); -- Comentário: Fim das soldas elétricas
